// 制度ごとの「詳細な試算」の定義（program.html の #ptSim セクションだけが読む）。
//
// 作り方：
//   金額・率・区分は暗記で書かない。必ず一次資料（制度所管省庁のご案内・交付要綱、
//   補助金なら当該公募回の公募要領）を開いて数値を拾い、source に出典URLと
//   確認日時を入れる。拾った内容は専門家レビュー（厚生労働省系 → sharoushi、
//   経済産業省・農林水産省・観光庁・国土交通省系 → shindanshi）に通し、review に記録を残す。
//
//   ご案内・リーフレットは要約なので、それだけで書かない。2026-08-05の監修で、
//   ご案内には「令和8年度地域別最低賃金未満であること」としか書かれていない要件が、
//   交付要綱では「令和7年度地域別最低賃金以上 かつ 令和8年度未満」という帯だと分かった。
//   ご案内だけを読んで噛み砕くと、要件の意味が反転する。要綱・要領・Q&Aまで見ること。
//
// 直すときの約束：
//   ・数値を変えたら source.checked を取り直した日時に更新し、review をやり直す
//   ・「申請すればもらえる」と読める書き方にしない。kind（hojo＝補助金／josei＝助成金）は
//     必ず入れる（結果の見出しと共通の注意書きが自動で変わる）
//   ・新しい計算タイプを増やす前に、既にある型で書けないか検討する。型が増えるほど
//     制度を1つ足すコストが上がる（地域限定の97制度をこのあと足すので、ここは特に守る）
//   ・迷ったら少なめに見積もる側へ倒す。ただし「判定できるのに諦める」のは別問題で、
//     入力から機械的に判定できる要件は when や derive で判定する
//     （特例事業者の賃金要件、引上げ労働者数の線引きがその例）
//   ・review は記録であって画面には出さない。実在の有資格者の監修ではないので、
//     「社労士監修」と読める表示をしてはいけない
//   ・締切は「いつまで」を1つに決めつけない。業務改善助成金のように
//     「Aの前日 か Bの日 の早いほう」という書き方の制度がある（片方を落とすと数か月ずれる）
//
// 制度を1つ足す手順：
//   1. その制度の要綱・公募要領を開く（暗記で書かない）
//   2. type を選ぶ（多くは expense_rate。上限額と補助率だけで決まるため）
//   3. エントリを書く（program.html 側のコードは触らない）
//   4. python _tools/check_sim_data.py で機械チェック
//   5. Playwright で program.html?key=<制度キー> を開き、実際に数字を入れて確かめる
//   6. 専門家レビュー → review に記録
//
// 計算タイプ（program.html の計算エンジンが解釈する語彙。ここにない語は動かない）：
//   expense_rate … min（経費 × 補助率、上限額）。補助率は固定値（fixed）／数値の
//                  しきい値（thresholds）／選択肢ごと（optionsOf。選択肢に rate を持たせる）／
//                  区分表（axes／values。3/4 と 4/5 のように条件で切り替わる制度）。
//                  上限額は固定値（fixedMan）か区分表（axes／values。軸は最大3つ）か
//                  足し算（sum。下記）。
//                  経費の聞き方は2通り。1つの質問で聞くなら expenseQ。取組ごとに
//                  「助成対象にできる経費そのものの上限」が違う制度は expenseParts で
//                  分けて聞く（[{ id, label, q, cap?, overNote? }]）。上限は部分ごとに
//                  当ててから足す。合計に1回だけ当てると、上限のない部分と混ざって
//                  上限が事実上消える（働き方改革推進支援助成金で20倍の過大になった）。
//                  下限は floor で書く。2種類あるので取り違えないこと：
//                    floor: { q, min, … }        … 対象経費そのものの下限（業務改善助成金の10万円）
//                    floor: { amount, … }        … 補助金の額の下限（AI導入補助金の5万円）
//                    floor: { amountBy:{q,values} } … 補助金の額の下限が枠ごとに違う場合
//                  そもそも受けられない組み合わせは blocks: [{ when, message }] で止める
//                  （成果目標を1つも選べていない、など）。上から順に見て、最初に
//                  当たったものの message を出す。条件の細かいものを先に書くこと。
//   per_person   … 単価 × 人数（上限あり）＋ 加算（adds）。単価は区分表（axes／values）で引く。
//                  countQ を書かなければ「1事業所あたり」の定額制度になる。
//   checkbox_sum … 当てはまる取組ごとの定額を合算する型。1つの制度の中に独立した助成が
//                  何本もあり、本数ごとに人数の上限が別々に決まっている制度のためのもの。
//                  calc: { type:'checkbox_sum', q:'<checkbox質問のid>' } と書き、
//                  額は checkbox の option 側に持たせる：
//                    man / manBy:{q,values}      … 額（manBy はほかの質問の答えで変わる場合）
//                    countQ / maxCount / overNote … その項目だけ人数倍する
//                    requires / requiresNote      … これを取っていないと取れない項目
//                    excludes / excludesNote      … これと同時には取れない項目
//                    when / whenNote              … 条件を満たすときだけ足す
//                  取れない組み合わせは黙って落とさず、理由を注記に出す。
//   multi_part   … 性格の違う助成を足し合わせる型。1つの申請の中に、計算のしかたが
//                  違う部品が並ぶ制度のためのもの。
//                    人材開発支援助成金       … 経費助成＋賃金助成＋OJT実施助成
//                    育休中等業務代替支援コース … 業務体制整備経費＋業務代替手当の3/4
//                  calc: { type:'multi_part', parts:[…], cap?, adds? } と書く。
//                  部品（parts）の kind は次の3つだけで、いずれも既にある計算を呼ぶ：
//                    fixed        … man / manBy:{q,values}
//                    expense_rate … expenseQ, rate（fixed／axes／thresholds／optionsOf）, cap
//                    per_person   … unit（区分表）× countQ ×（あれば）hoursQ
//                  どの部品にも when / whenNote を付けられる。「別の型を選んだから
//                  出ない」だけで説明が要らないときは whenNote のかわりに
//                  whenSilent: true と書く（黙って消しているのか、意図して黙って
//                  いるのかを、あとから読んで区別できるようにするため）。
//                  部品の cap に perCountQ を書くと「1人あたりの上限 × 人数」
//                  「1か月あたりの上限 × 月数」になる（maxPerCount で頭打ち）。
//                  calc.cap は制度全体の上限（人材開発の1事業所1年度1,000万円）。
//                  top.capKey は、全体の上限が無い制度では '部品のid:区分表のキー' で指す。
//   none         … 金額の試算になじまない制度（reason に理由を書いて公式サイトへ誘導する）
//
// 上限の足し算（cap.sum）：
//   上限そのものが「選んだ項目ごとの額の足し算」で決まる制度（働き方改革推進支援助成金の
//   成果目標＋加算、支給要領 表3 の取組ごとの経費上限）のために使う。
//     cap: { label, sum: [{ id, label, fixedMan | axes+values, when?, whenSilent?,
//                           needs?, perCountQ?, maxPerCount?, overNote? }] }
//   when  … その項目を選んでいるか。外れたら数えない（説明が要らないときは whenSilent: true）
//   needs … 選んではいるが、制度上の前提を満たさないので0になる条件。
//           [{ when, note }] の並びで書く。落ちる理由は複数ありうる（人数を入れていない／
//           解雇があった／規模と人数が噛み合わない）ので、1つに畳むと理由が言えなくなる。
//           note は必ず画面に出す。黙って落とすと「選んだのに増えない」としか見えない。
//   top.capKey は '項目のid' か '項目のid:区分表のキー' で、その項目1つ分を名指しする。
//
// when に書ける条件（区分・部品・sum の項目・blocks で共通）：
//   { q, lt/lte/gte/gt }    … 数値の比較
//   { q, eq }               … 選択肢の一致
//   { q, has:'<選択肢の値>' } … checkbox でその項目を選んでいるか
//   { sum:['q1','q2'], gt } … 複数の質問の答えを足した値で比較（費用の合計額など）
//   { all:[…] } / { any:[…] } / { not:{…} } … 組み合わせ
//
// 質問の型：
//   number      … 数値入力
//   choice      … プルダウン（options の v/t/s。s は計算の内訳に出す短い名前、
//                  add は「その選択肢が持つ加算額」で number_list の判定に使う）
//   checkbox    … 複数選択
//   number_list … ほかの質問の人数に合わせて入力欄を並べ、1件ずつの値から
//                  計算に使う値（derive）を機械的に出す型。
//                  countQ＝欄の数を決める質問／maxFields＝これを超えたら1欄に畳む／
//                  rowFlag＝行ごとのチェック（excludeFromMin で最小値の判定から外す）／
//                  derive＝[{id, how:'min'} , {id, how:'countBelow', base, plusFrom, dropNote}]
//                  derive で作った値は、質問の答えと同じ名前で cap の軸や when から参照できる。
//
// top ブロック（トップページが読む値。2026-08-05 に一本化）：
//   上限額・補助率・受付期間を index.html と両方に書いていたせいで、片方だけ古い状態が
//   4件見つかった（ものづくりの締切、持続化の枠と上限、省力化の受付回、空き家の補助率）。
//   そこで、これらは top に置き、index.html は起動時にここから読む形にした。
//   index.html 側に同じ制度の CAP / CAP_TEXT / RATE_BASE / PROGRAM_TRACKS を
//   書き残すと _tools/check_sim_data.py が落ちる。
//
//   top: {
//     rate, cap, schedule … 一覧と制度詳細ページに出す説明文（PROGRAMS[key] の同名項目になる）
//     capKey              … 概算に使う上限額。数字は書かず calc.cap.values のキーで指す
//                           （書き写すと必ず片方が古くなる。fixedMan の制度は省略）
//     capText             … 上限額の表示。capKey が指す額を必ず含めること（機械チェックあり）
//     tracks              … 枠・コースの選択肢。上限は capKey / capKeyByTier で指す。
//                           calc に無い枠（AI導入のインボイス枠など）だけ capMan に直書きし、
//                           なぜ calc に無いのかをコメントで残す
//     noTopEstimate       … true なら概算の対象から外す（金額を出せない制度）
//   }
//   補助率の基本値（RATE_BASE）は calc から自動で出す（いちばん低い率＝安全側）ので書かない。
//
// 画面の作り（全制度で守る）：
//   ・見出しのすぐ下は入力欄にする。趣旨の説明は質問の後ろ（開閉式）へ回す。
//     読ませてから触らせるより、触らせてから読ませるほうが最後まで届く。
//   ・質問は1問ずつ開く。だから質問の並びは「答えやすい順」ではなく
//     「前の答えが次の質問の前提になる順」にする
//
// 注意書きの書き方：
//   ・[[ ]] で囲んだところは赤の太字になる。これに当たると金額や可否が変わる条件だけを囲む
//     （囲みすぎると、どれが効く条件か分からなくなって強調の意味が消える）
//   ・2段に分ける
//       notes     … 金額と可否に直結するもの。常に表示する。多くても4〜5個まで
//       notesMore … そのほかの条件。既定は閉じた開閉式にする（全部並べると誰も読まない）
//
// 定義が無い制度は、program.html 側が自動で「準備中」の案内（上限額・補助率の文章を再掲）を
// 出す。だから未対応の制度があっても画面は壊れない。

