                  // ご案内は「前年度」と書いているが、要領と申出書は「前年同期」。要領に合わせる。
                  elseNote: '10人以上を引き上げても、特例事業者に当たらない場合の上限額は「8人以上」の額です。直近6か月平均の売上高総利益率（粗利率）または売上高営業利益率が、前年の同じ時期と比べて3％ポイント以上下がっている場合は特例事業者に当たり、上限額が上がります（申出書と月次の損益計算書などが必要です）。'
