        '引き上げ前の事業場内最低賃金より低い賃金の人がいる場合は、その人が雇用保険に入っているかどうかにかかわらず、新しい額まで引き上げる必要があります。',
        // 交付要領 第2の6
        '同じ事業主が複数の店舗・事務所で申請する場合、事業主あたりの年間の申請額は合計600万円までです。3店舗でそれぞれ上限まで申請できるわけではありません。',
        '下限の10万円は消費税を含まない額で判断します（税込10万4,500円でも、税抜9万5,000円なら対象外です）。税抜10万円以上の契約では、原則として同じ条件で2社以上の見積もりが必要です。',
