        'パソコン・タブレット・スマートフォンは原則として対象外ですが、POSレジや会計給与システムなど、特定の業務専用のシステムを動かす目的だとはっきりしている場合は、対象になることがあります。対象外の自動車は「特種用途自動車（8ナンバー・福祉車両など）以外」で、特種用途自動車は対象になります。',
        '委託費のうち、就業規則の作成・改正と賃金制度の整備にかかる費用は対象になりません。経営コンサルティング経費も、人員削減や労働条件の引き下げを内容とするものは対象外です。',
        '免税事業者などは消費税を含めた額で申請できる場合があります（その場合の助成額は、この試算より少し多くなります）。委託費のうち、就業規則の作成・改正と賃金制度の整備にかかる費用は対象になりません。',
