        // Q&A問13
        '事業場内最低賃金の人が、賃金を引き上げる前に産前産後休暇や育児休業に入り、引き上げ後の賃金の支払いが全く無い場合は対象になりません（実績報告までに復帰して1日でも勤務し、引き上げ後の賃金が支払われていれば対象になります）。',
        '同じ事業所からの申請は年度内1回までです。',
        '予算の範囲内で交付するため、申請期間の途中で受付が終わることがあります。',
