    // ================================================================
    // デジタル化・AI導入補助金2026（旧IT導入補助金）通常枠
    // 出典：通常枠 公募要領（2026-08-05 取得）「２－３ 補助対象経費、補助率及び補助額」
    //       https://it-shien.smrj.go.jp/wp-content/uploads/2026/03/digital_ai_normal_koubo.pdf
    //   補助額 5万円〜150万円未満（1プロセス以上）／150万円〜450万円以下（4プロセス以上）
