          + ' 2回目（独立監査）：インボイス枠（tracks、通常枠とは別の情報表示欄）の説明が「小規模事業者は3/4に優遇」となっていたが、実際は事業者規模ではなく金額帯（50万円以下/超）で率が変わる制度で、規模による優遇という説明は誤り。1機能のみの場合の上限50万円やPC・タブレット等・レジ券売機の別枠（率1/2）も抜けていた。desc・capTextを金額帯構造に基づく正確な説明に書き換え、rateは50万円超の範囲の実際の率（2/3、少なめに出る側）のまま残した。'
