        '[[出勤簿にハンコを押すだけの勤怠管理では対象外]]です（休暇制度と在宅勤務等を除く）。変形労働時間制・フレックス・事業場外みなし・裁量労働・管理監督者の適用者は、休暇制度と在宅勤務等しか対象になりません。',
        'もともと残業がなく今後も見込みがない人について「残業免除を利用した」とすることはできません。',
        '過去に旧・不妊治療両立支援コースを受け取った事業主は、不妊治療の区分は受け取れません（月経・更年期は新たに要件を満たせば対象です）。',
        '[[常時10人未満のサロンは、就業規則を作っていなくても対象になります]]（要領0301a イ）。その場合は制度を明文化して全員に知らせ、その日付が分かるもの（全員へのメール、回覧、掲示の写真、労働者代表の氏名と周知日が入った申立書など）を用意します。就業規則が無いことを理由にあきらめる必要はありません。',
        '年次有給休暇そのものは使えませんが、[[失効した年次有給休暇を積み立てて不妊治療などに使える制度は対象になります]]（要領0301a ニ(ｲ)）。新しく休暇を作らずに済むので、現実的な打ち手のひとつです。',
