          + ' 2回目（独立監査）：産前産後休業から続けて育休に入る場合の準備期限の記述が、要領0301a ロ・ハ・ニの2パターン（産前休業から連続する場合／産前休業を取らず産後休業から連続する場合）を取り違えており、産前休業を取らないケース（美容室で多い）で本来より遅い日を締切と誤認させる書き方になっていた。2パターンを正しく書き分けた。'
