        cap: '<strong>1事業主あたり無期雇用1人＋有期雇用1人の計2人まで</strong>です。同じ雇用形態から2人は取れません。無期か有期かはプランの策定日の時点で判断します。理論上の最大は（30万円＋30万円）×2人＋情報公表加算2万円＝122万円ですが、これは<strong>無期のスタッフと有期のスタッフの両方がそれぞれ連続3か月以上の育休を取り、復帰後6か月以上続けて働き、その6か月の就業割合が5割以上だった事業所</strong>だけです。片方の雇用形態しかいないサロンの上限は62万円になります。プラチナくるみん15万円加算と有期雇用10万円加算は、このコースにはありません',
