      notes: [
        '【このコースに計画届はありません】そのかわり、①育休制度と育児のための短時間勤務制度の就業規則への規定は[[育休開始日の前日まで]]、②業務代替手当の賃金制度の規定・業務の見直し・代替者との面談は[[業務代替期間の開始日まで]]、③原職等に復帰させる旨の規定は[[対象者が職場復帰するまで]]に済ませます。あとからさかのぼって規定することはできません。',
        '[[対象になるスタッフは、育休（時短）開始日にも支給申請日にも雇用保険被保険者である必要があります]]（要領0301a1 イ(ﾍ)・0301b イ(ﾄ)）。[[手当を払う相手（業務代替者）も、その事業主が雇用する労働者でなければなりません]]（同0301a1 イ(ｲ)）。[[業務委託や面貸しのスタイリストは、育休を取る側としても、仕事を引き受ける側としても数えられません]]。復帰後にパート等に変わって被保険者でなくなった場合も対象外です。',
        '[[この金額は対象者1人あたりです]]。ただし[[業務体制整備経費（2万・3万・6万・20万円）は1事業主の1人目に1回だけ]]なので、2人目以降は手当の分だけになります。[[1事業主が申請できるのは1年度に3つの型を合わせて延べ10人まで、しかも初回の対象者が出てから5年間]]です（くるみん認定を受けた事業主は令和12年度まで延べ50人が限度）。',
        '短時間勤務の代替を選ぶ場合、対象になるのは[[1日の所定労働時間が7時間以上の人について、1日の所定労働時間を1時間以上短縮する制度]]です（要領0301b イ(ｲ)）。[[6時間の人を1時間短縮しても、7時間の人を30分短縮しても対象外]]です。シフト制のサロンでは、ここで落ちることがよくあります。',
        '[[業務体制整備経費だけでの申請はできません]]。対象になるスタッフの育休は[[7日以上]]必要です。育休が1か月以上の場合は、[[職場復帰後3か月以上、雇用保険被保険者として続けて雇う]]必要があり、その3か月は[[就業予定日の5割以上]]働いていることが条件です。'
      ],
      notesMore: [
        '育児休業制度と育児のための短時間勤務制度の両方を、対象者の育休開始日（時短は利用開始日）の前日までに就業規則に定めていること。あわせて一般事業主行動計画を作り、労働局へ届け出て、公表・周知し、申請時に有効であることが必要です（プラチナくるみん認定事業主は除く）。',
        '新しく人を雇う型には、代替要員そのものへの条件があります。[[所定労働時間が育休を取る人の2分の1以上]]であること（複数名なら合算できます）、[[雇用契約や派遣契約の始期が、妊娠の事実を事業主が知った日以降]]であること（すでに働いている人を充てることはできません）、[[育休を取る人に業務に係る手当が出ているなら、代替要員にも同じ手当を出す]]こと（雇用形態が違うことを理由に出さないと対象外）です（要領0301c ロ）。',
        '短時間勤務の代替は、[[制度利用期間の初日から1か月のうち所定労働日の5割以上働き、そのうち8割以上を制度どおりの短い時間で勤務している]]ことが必要です（要領0301b イ(ﾍ)）。満たさない月は短時間勤務をしたものと扱われず、その月の手当が助成の対象から落ちます。',
        '育児休業中に臨時的・一時的に働いてもらった場合、[[1か月ごとに見て就業日数が10日を超え、かつ就業時間が80時間を超えると、その1か月は育児休業をしていないものと扱われます]]（Q&A 問代期3）。その月に業務代替期間があっても助成の対象になりません。「忙しい日だけ入ってもらう」がここに当たります。',
        '情報公表加算2万円を足せるのは、育休取得時（育休1か月未満の場合はその申請）・短時間勤務開始時・新規雇用の申請です（要領0302d）。[[職場復帰時の申請には加算できません]]。',
        '短時間勤務の代替は「子が3歳に達する月まで」が対象で、要領に月数の上限は書かれていません。このツールでは最長36か月として計算しています。',
        '出勤簿にハンコを押すだけの勤怠管理だと、短時間勤務の代替は対象外です。',
        '出生時両立支援コース・育児休業等支援コースとは併用できます（Q&A 問代共6）。',
        '申請書類の作成・提出を代理で頼めるのは社会保険労務士または弁護士に限られます。'
      ]
