    //
    // 出典（2026-08-05 に取得）：
    //   ご案内（令和8年8月3日版・66ページ）https://www.mhlw.go.jp/content/11800000/001731967.pdf
    //   支給要領（令和8年8月3日版・109ページ）https://www.mhlw.go.jp/content/11800000/001731969.pdf
